"""
services/refund/queue_client.py
Thin wrapper around boto3 SQS client for the refund-requests queue.
Added in PR #3391.
"""

import json
import boto3

QUEUE_URL = "https://sqs.ap-northeast-1.amazonaws.com/482910337651/refund-requests"


class RefundQueueClient:
    def __init__(self):
        self._sqs = boto3.client("sqs", region_name="ap-northeast-1")

    def enqueue(self, queue_name, payload):
        self._sqs.send_message(
            QueueUrl=QUEUE_URL,
            MessageBody=json.dumps(payload),
        )

    def receive(self, max_messages=10, wait_time_seconds=10):
        resp = self._sqs.receive_message(
            QueueUrl=QUEUE_URL,
            MaxNumberOfMessages=max_messages,
            WaitTimeSeconds=wait_time_seconds,
            VisibilityTimeout=30,
        )
        return resp.get("Messages", [])

    def delete(self, receipt_handle):
        self._sqs.delete_message(
            QueueUrl=QUEUE_URL,
            ReceiptHandle=receipt_handle,
        )

# refund-requests is a standard (non-FIFO) queue, 30s visibility timeout
